const empty = (title, detail) => `<section class="command-empty"><strong>${title}</strong><p>${detail}</p></section>`;

const title = (heading, subtitle, actions = '') => `<div class="command-head"><div><p class="eyebrow">ศูนย์บัญชาการข้อมูลโรคระดับอำเภอ</p><h1>${heading}</h1><p>${subtitle}</p></div>${actions}</div>`;

const read506 = () => {
  try { return JSON.parse(localStorage.getItem('ndss-506-records') || '[]'); }
  catch { return []; }
};
const readImportMeta = () => {
  try { return JSON.parse(localStorage.getItem('ndss-506-import-meta') || 'null'); }
  catch { return null; }
};

const readCases = () => {
  try { return JSON.parse(localStorage.getItem('ndss-investigations') || '[]'); }
  catch { return []; }
};
const readTasks = () => {
  try { return JSON.parse(localStorage.getItem('ndss-response-tasks') || '[]'); }
  catch { return []; }
};
const readContacts = () => {
  try { return JSON.parse(localStorage.getItem('ndss-case-contacts') || '[]'); }
  catch { return []; }
};
const readAudit = () => {
  try { return JSON.parse(localStorage.getItem('ndss-audit-log') || '[]'); }
  catch { return []; }
};
const readLab = () => {
  try { return JSON.parse(localStorage.getItem('ndss-lab-results') || '[]'); }
  catch { return []; }
};
const readAlertState = () => {
  try { return JSON.parse(localStorage.getItem('ndss-alert-state') || '{}'); }
  catch { return {}; }
};
const readAiReports = () => {
  try { return JSON.parse(localStorage.getItem('ndss-ai-reports') || '[]'); }
  catch { return []; }
};

const values = () => {
  const rows = read506();
  const cases = readCases();
  const byDisease = rows.reduce((all, row) => {
    const key = row.disease || 'ไม่ระบุโรค'; all[key] = (all[key] || 0) + 1; return all;
  }, {});
  const byTambon = rows.reduce((all, row) => {
    const key = row.tambon || row.district || 'ไม่ระบุพื้นที่'; all[key] = (all[key] || 0) + 1; return all;
  }, {});
  return { rows, cases, byDisease, byTambon };
};

const clusterSignals = () => {
  const records=[...read506(),...readCases()];
  const week = value => { const date=new Date(value); if(Number.isNaN(date)) return ''; const first=new Date(date.getFullYear(),0,1); return `${date.getFullYear()}-W${String(Math.ceil((((date-first)/86400000)+first.getDay()+1)/7)).padStart(2,'0')}`; };
  const grouped=records.reduce((all,row) => { const period=week(row.onset || row.createdAt); const area=row.tambon || row.subdistrict || row.district || 'ไม่ระบุพื้นที่'; const disease=row.disease || 'ไม่ระบุโรค'; if(!period || disease==='ไม่ระบุโรค') return all; const key=[disease,area,period].join('|'); all[key]=all[key] || {disease,area,period,count:0,records:[]}; all[key].count++; all[key].records.push(row); return all; },{});
  return Object.values(grouped).filter(item=>item.count>=3).sort((a,b)=>b.count-a.count);
};

const statCards = items => `<section class="command-stats">${items.map(([label, value, note, tone = 'blue']) => `<article class="${tone}"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`).join('')}</section>`;

const ranked = (source, label) => {
  const entries = Object.entries(source).sort((a,b) => b[1] - a[1]).slice(0, 10);
  if (!entries.length) return empty('ยังไม่มีข้อมูล', `ยังไม่มีข้อมูล ${label} จากการนำเข้า รง.506`);
  const max = entries[0][1] || 1;
  return `<div class="ranked-list">${entries.map(([name,count], index) => `<div><b>${index + 1}</b><span>${name}</span><i><em style="width:${Math.max(8, count / max * 100)}%"></em></i><strong>${count} ราย</strong></div>`).join('')}</div>`;
};

const overview = () => {
  const { rows, cases, byDisease, byTambon } = values();
  return `${title('ภาพรวมสถานการณ์โรค', 'ข้อมูลจากระบบ รง.506 และแบบสอบสวนโรคออนไลน์ · ข้อมูลจะอัปเดตเมื่อมีการนำเข้าหรือบันทึกเคสใหม่', '<div class="command-actions"><button class="secondary" data-open-506-import>＋ นำเข้า รง.506</button><button class="primary" data-view="reports">✦ สรุปรายเดือน</button></div>')}${statCards([['ผู้ป่วยจาก รง.506', `${rows.length} ราย`, 'ข้อมูลสะสมที่นำเข้า', 'blue'], ['คิวสอบสวน', `${cases.length} ราย`, 'จากแบบสอบสวนโรคออนไลน์', 'orange'], ['พื้นที่มีรายงาน', `${Object.keys(byTambon).length} พื้นที่`, 'ตามขอบเขตข้อมูลที่นำเข้า', 'green'], ['โรคที่รายงาน', `${Object.keys(byDisease).length} โรค`, 'ไม่เปรียบเทียบข้ามขอบเขต', 'purple']])}<section class="command-grid"><article class="work-panel"><div class="panel-top"><h2>10 อันดับโรคที่มีรายงาน</h2><small>หน่วย: ราย</small></div>${ranked(byDisease,'โรค')}</article><article class="work-panel"><div class="panel-top"><h2>พื้นที่ที่มีรายงาน</h2><small>ตามตำบล/อำเภอที่มีในไฟล์</small></div>${ranked(byTambon,'พื้นที่')}</article></section>`;
};

const importer = () => {
  const meta=readImportMeta();
  const rows=read506();
  const incomplete=rows.filter(row=>!row.disease || !row.onset || !(row.tambon || row.district)).slice(0,10);
  return `${title('นำเข้าข้อมูล รง.506', 'อัปโหลดไฟล์ Excel หรือ CSV เพื่อนำมาใช้ใน Dashboard, แผนที่ และคิวสอบสวน')}<section class="work-panel import-panel"><div class="import-drop"><span>⇧</span><h2>เลือกไฟล์รายงาน รง.506</h2><p>รองรับไฟล์ .xlsx, .xls และ .csv · ระบบอ่านแถวแรกเป็นชื่อคอลัมน์</p><input id="import-506-file" type="file" data-import-506 accept=".xlsx,.xls,.csv,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" /><label class="primary" for="import-506-file">เลือกไฟล์</label></div><div class="import-guide"><h2>คอลัมน์ที่ระบบพยายามตรวจจับ</h2><p>โรค / Disease, วันที่เริ่มป่วย / Onset date, เพศ / Sex, อายุ / Age, ตำบล / Tambon, อำเภอ / District และพิกัด Lat/Lng</p><p class="subtle">ระบบกันข้อมูลซ้ำจาก โรค + วันเริ่มป่วย + พื้นที่ + ชื่อผู้ป่วย (ถ้ามี) และแจ้งแถวที่ควรตรวจสอบก่อนใช้วิเคราะห์</p></div></section><section class="work-panel"><div class="panel-top"><h2>สถานะการนำเข้าล่าสุด</h2><button class="secondary" data-clear-506>ล้างข้อมูลนำเข้า</button></div><div data-import-status>${rows.length ? `มีข้อมูล รง.506 ${rows.length} รายในเครื่องนี้` : 'ยังไม่มีข้อมูลนำเข้า'}</div>${meta ? `<div class="import-quality"><span><b>${meta.imported}</b> รายการใหม่</span><span><b>${meta.duplicates}</b> รายการซ้ำ</span><span><b>${meta.incomplete}</b> รายการควรตรวจสอบ</span><small>${meta.fileName} · ${meta.at}</small></div>` : '<p class="subtle">ยังไม่มีประวัติการตรวจสอบไฟล์</p>'}</section><section class="work-panel"><div class="panel-top"><h2>ตรวจสอบคุณภาพข้อมูล</h2><small>แสดงสูงสุด 10 รายการที่ขาดข้อมูลสำคัญ</small></div>${incomplete.length ? `<div class="history-table-wrap"><table><thead><tr><th>ผู้ป่วย / HN</th><th>โรค</th><th>วันเริ่มป่วย</th><th>ตำบล / อำเภอ</th><th>สถานะ</th></tr></thead><tbody>${incomplete.map(row=>`<tr><td>${row.patient || row.hn || '-'}</td><td>${row.disease || '<mark class="red">ไม่ระบุ</mark>'}</td><td>${row.onset || '<mark class="red">ไม่ระบุ</mark>'}</td><td>${row.tambon || row.district || '<mark class="red">ไม่ระบุ</mark>'}</td><td><mark class="orange">ควรตรวจสอบ</mark></td></tr>`).join('')}</tbody></table></div>` : rows.length ? '<p class="ok">✓ ไม่พบรายการที่ขาดโรค วันเริ่มป่วย หรือพื้นที่</p>' : empty('ยังไม่มีข้อมูลสำหรับตรวจสอบ', 'นำเข้าไฟล์ รง.506 เพื่อเริ่มตรวจสอบคุณภาพข้อมูล')}</section>`;
};

const areaMap = () => {
  const { rows, byTambon, byDisease } = values();
  const namedAreas=Object.entries(byTambon).sort((a,b)=>b[1]-a[1]).slice(0,8);
  return `${title('แผนที่ & ข้อมูลรายตำบล', 'แสดงขอบเขตพื้นที่ จุดรายงาน และสรุปสถานการณ์ตามข้อมูลที่บันทึก', '<div class="command-actions"><button class="secondary" data-view="reports">▣ พิมพ์สรุป</button><button class="primary" data-open-506-import>＋ นำเข้า Excel</button></div>')}<section class="map-command-toolbar no-print"><label>เลือกโรค (แผนที่)<select data-command-map-scope><option value="all">ทุกโรค</option>${Object.keys(byDisease).map(d => `<option>${d}</option>`).join('')}</select></label><span>ชั้นข้อมูล: ขอบเขตอำเภอ / ตำบล และหมุดเคส</span></section><section class="command-map-layout reference-map-layout"><article class="work-panel command-map-panel"><div class="panel-top"><div><h2>▤ แผนที่สถานการณ์โรค</h2><small>Leaflet.js · เลือกอำเภอ/ตำบลจากช่องค้นหาด้านบนแผนที่เพื่อซูมและสร้าง PDF รายพื้นที่</small></div></div><div class="command-map" data-command-map></div></article><aside class="reference-map-side"><article class="work-panel map-layer-card"><h2>◉ ชั้นข้อมูล</h2><p><i class="map-layer-point red"></i> ระดับเฝ้าระวังสูง (5+ เคส)</p><p><i class="map-layer-point orange"></i> ระดับเฝ้าระวังปานกลาง (2–4 เคส)</p><p><i class="map-layer-point green"></i> มีรายงาน (1 เคส)</p><p><i class="map-layer-point blue"></i> ยังไม่มีรายงาน</p><small>ขอบเขต GIS: อำเภอและตำบลของจังหวัดนราธิวาส</small></article><article class="work-panel"><div class="panel-top"><h2>▤ สรุปรายตำบล</h2><small>${namedAreas.length} พื้นที่</small></div>${namedAreas.length ? `<div class="map-area-rank">${namedAreas.map(([name,count],index)=>`<div><b>${index+1}</b><span><strong>${name}</strong><small>จำนวนรายงานในขอบเขตข้อมูล</small></span><em>${count} ราย</em></div>`).join('')}</div>` : empty('ยังไม่มีข้อมูลพื้นที่', 'นำเข้า รง.506 หรือบันทึกแบบสอบสวนเพื่อแสดงสรุปพื้นที่')}</article></aside></section>${rows.length ? '' : '<p class="scope-note">ยังไม่มีข้อมูล รง.506 ในอุปกรณ์นี้ — แผนที่จะยังแสดงขอบเขต GIS และสามารถรับหมุดจากแบบสอบสวนโรคออนไลน์ได้</p>'}`;
};

const queue = () => {
  const { cases } = values();
  const tasks=readTasks();
  const grouped=cases.reduce((all,item,index)=>{ const area=item.subdistrict || item.tambon || item.district || item.location || 'ไม่ระบุพื้นที่'; all[area]=all[area] || {area,cases:[],diseases:new Set()}; all[area].cases.push({...item,index}); if(item.disease) all[area].diseases.add(item.disease); return all; },{});
  const rows=Object.values(grouped).map(group=>{ const completed=group.cases.filter(item=>tasks.some(task=>Number(task.caseIndex)===item.index && task.status==='ควบคุมแล้ว')).length; const pending=group.cases.length-completed; return {...group,completed,pending,events:group.diseases.size}; }).sort((a,b)=>b.pending-a.pending || b.cases.length-a.cases.length);
  const urgent=tasks.filter(task=>task.priority==='เร่งด่วน' && task.status!=='ควบคุมแล้ว').length;
  return `${title('Qutbreak Management', 'จัดการเหตุการณ์และคิวสอบสวนตามพื้นที่จากแบบสอบสวนโรคออนไลน์และงานติดตามของทีม SRRT', '<button class="primary" data-view="investigation">＋ เปิดแบบสอบสวนโรค</button>')}<section class="queue-note"><b>ข้อมูลในหน้านี้มาจากรายการที่บันทึกในระบบ</b><span>ระบบจัดกลุ่มตามพื้นที่เพื่อให้ทีมตรวจสอบ มอบหมาย และติดตามงานได้เร็วขึ้น ไม่ใช่การยืนยันเหตุการณ์ระบาด</span></section>${statCards([['ผู้ป่วยที่เข้าเกณฑ์คิว', `${cases.length} ราย`, 'จากแบบสอบสวนที่บันทึก', 'blue'], ['งานสอบสวนทั้งหมด', `${tasks.length} งาน`, 'งานที่มีการมอบหมายแล้ว', 'purple'], ['งานเร่งด่วน', `${urgent} งาน`, 'สถานะยังไม่ปิด', 'red'], ['บันทึกผลแล้ว', `${tasks.filter(task=>task.status==='ควบคุมแล้ว').length} งาน`, 'ตามงานติดตาม', 'green']])}<section class="work-panel"><div class="queue-filter"><div><b>ตัวกรองคิวงาน</b><button class="active" data-queue-filter="all">ทั้งหมด</button><button data-queue-filter="pending">ยังไม่สอบสวนครบ</button><button data-queue-filter="event">มีหลายโรค</button><button data-queue-filter="done">ดำเนินการแล้ว</button></div><input class="table-search" data-command-queue-search placeholder="ค้นหาพื้นที่, โรค, ผู้ป่วย" /></div>${rows.length ? `<div class="history-table-wrap"><table class="queue-area-table"><thead><tr><th>#</th><th>พื้นที่</th><th>เหตุการณ์/โรค</th><th>เคส</th><th>สอบสวนแล้ว</th><th>ยังไม่สอบสวน</th><th>สถานะ</th><th>ดำเนินการ</th></tr></thead><tbody data-command-queue-rows>${rows.map((row,index)=>{ const kind=row.completed===row.cases.length?'done':row.events>1?'event':'pending'; return `<tr data-queue-kind="${kind}"><td>${index+1}</td><td><b>${row.area}</b><br/><small>${row.cases.slice(0,2).map(item=>item.patient || item.hn || '-').join(', ')}</small></td><td>${[...row.diseases].slice(0,2).join(', ') || '-'}${row.diseases.size>2 ? ` +${row.diseases.size-2}` : ''}</td><td><b>${row.cases.length}</b></td><td><mark class="green">${row.completed}</mark></td><td><mark class="${row.pending?'gold':'green'}">${row.pending}</mark></td><td><mark class="${row.pending?'orange':'green'}">${row.pending?'รอติดตาม':'เสร็จสิ้น'}</mark></td><td><button class="table-action" data-view="tracking">เปิดติดตาม</button></td></tr>`; }).join('')}</tbody></table></div>` : empty('ยังไม่มีคิวสอบสวน', 'เริ่มต้นด้วยการเปิดแบบสอบสวนโรคออนไลน์และบันทึกเคส')}</section>`;
};

const clusters = () => {
  const signals=clusterSignals();
  return `${title('ตรวจจับกลุ่มก้อนโรค', 'คัดกรองรายการที่มีรายงานโรคเดียวกันในพื้นที่เดียวกันภายในสัปดาห์เดียวกัน เพื่อให้ทีม SRRT ตรวจสอบ')}<section class="cluster-rule"><b>เกณฑ์คัดกรองปัจจุบัน</b><span>ตั้งแต่ 3 ราย · โรคเดียวกัน · พื้นที่เดียวกัน · สัปดาห์เริ่มป่วยเดียวกัน</span><small>เป็นสัญญาณคัดกรองเชิงพรรณนา ไม่ใช่การยืนยันการระบาดหรือสรุปสาเหตุ</small></section>${statCards([['สัญญาณที่พบ', `${signals.length} กลุ่ม`, 'ตามเกณฑ์คัดกรอง', 'orange'], ['เคสในสัญญาณ', `${signals.reduce((sum,item)=>sum+item.count,0)} ราย`, 'รวมทุกกลุ่มที่เข้าเงื่อนไข', 'blue'], ['เกณฑ์ที่ใช้', '3 ราย', 'ปรับใช้โดยผู้ดูแลได้ในอนาคต', 'purple'], ['สถานะ', signals.length?'รอตรวจสอบ':'ยังไม่มีข้อมูล', 'ต้องตรวจทานโดย SRRT', 'green']])}<section class="work-panel"><div class="panel-top"><h2>รายการที่ต้องตรวจสอบ</h2><button class="primary" data-view="investigation">เปิดแบบสอบสวนโรค</button></div>${signals.length ? `<div class="cluster-list">${signals.map((item,index)=>`<article><span class="cluster-index">${index+1}</span><div><h3>${item.disease}</h3><p>${item.area} · ${item.period}</p><small>รายงาน ${item.count} รายในช่วงข้อมูลเดียวกัน</small></div><strong>${item.count}<small>ราย</small></strong></article>`).join('')}</div>` : empty('ยังไม่พบกลุ่มที่เข้าเกณฑ์คัดกรอง', 'ระบบต้องมีข้อมูลโรค พื้นที่ และวันเริ่มป่วยอย่างน้อย 3 รายในสัปดาห์เดียวกัน')}</section>`;
};

const epidemiology = () => {
  const {rows,cases}=values();
  const all=[...rows,...cases];
  const diseases=[...new Set(all.map(item=>item.disease).filter(Boolean))].sort();
  const selected=localStorage.getItem('ndss-analytics-disease') || '';
  const records=selected ? all.filter(item=>item.disease===selected) : all;
  const areas=records.reduce((all,item)=>{ const key=item.tambon || item.subdistrict || item.district || 'ไม่ระบุพื้นที่'; all[key]=(all[key]||0)+1; return all; },{});
  const sexes=records.reduce((all,item)=>{ const key=item.sex || 'ไม่ระบุ'; all[key]=(all[key]||0)+1; return all; },{});
  const ageGroup=age => { const number=Number(age); return !Number.isFinite(number) ? 'ไม่ระบุ' : number<5?'0–4 ปี':number<15?'5–14 ปี':number<60?'15–59 ปี':'60 ปีขึ้นไป'; };
  const ages=records.reduce((all,item)=>{ const key=ageGroup(item.age); all[key]=(all[key]||0)+1; return all; },{});
  const dated=records.filter(item=>item.onset || item.createdAt);
  const latest=dated.map(item=>new Date(item.onset || item.createdAt)).filter(date=>!Number.isNaN(date)).sort((a,b)=>b-a)[0];
  return `${title('สถานการณ์ระบาดวิทยา', 'วิเคราะห์ข้อมูลแบบ Person · Place · Time จากรายการจริงในระบบ')}<section class="work-panel analytics-filter"><label>เลือกโรคสำหรับวิเคราะห์<select data-disease-analytics-select><option value="">ทุกโรค</option>${diseases.map(disease=>`<option value="${disease}" ${selected===disease?'selected':''}>${disease}</option>`).join('')}</select></label><small>ข้อมูล ณ วันที่: ${latest ? latest.toLocaleDateString('th-TH') : 'ยังไม่มีข้อมูล'}</small></section>${statCards([['ผู้ป่วยในขอบเขต', `${records.length} ราย`, selected || 'ทุกโรค', 'blue'], ['พื้นที่ที่มีรายงาน', `${Object.keys(areas).length} พื้นที่`, 'ตามข้อมูลที่บันทึก', 'green'], ['ข้อมูลวันเริ่มป่วย', `${dated.length} ราย`, 'ใช้วิเคราะห์ตามเวลาได้', 'purple'], ['แบบสอบสวน', `${cases.filter(item=>!selected || item.disease===selected).length} ราย`, 'มีรายละเอียดการสอบสวน', 'orange']])}${records.length ? `<section class="command-grid"><article class="work-panel"><div class="panel-top"><h2>Person · กลุ่มอายุ</h2><small>หน่วย: ราย</small></div>${ranked(ages,'กลุ่มอายุ')}</article><article class="work-panel"><div class="panel-top"><h2>Person · เพศ</h2><small>หน่วย: ราย</small></div>${ranked(sexes,'เพศ')}</article><article class="work-panel"><div class="panel-top"><h2>Place · พื้นที่ที่มีรายงาน</h2><small>เรียงตามจำนวนรายงาน</small></div>${ranked(areas,'พื้นที่')}</article><article class="work-panel"><div class="panel-top"><h2>Time · วันเริ่มป่วย</h2><small>ข้อมูลที่มีวันเริ่มป่วย</small></div>${ranked(dated.reduce((all,item)=>{const date=new Date(item.onset || item.createdAt); const key=Number.isNaN(date)?'ไม่ระบุ':date.toLocaleDateString('th-TH'); all[key]=(all[key]||0)+1; return all;},{}),'วันเริ่มป่วย')}<p class="analysis-note">เป็นการแสดงการกระจายตามเวลาจากข้อมูลที่มี ไม่สรุปสาเหตุการเพิ่มขึ้นหรือลดลง</p></article></section>` : empty('ยังไม่มีข้อมูลสำหรับวิเคราะห์', 'นำเข้าข้อมูล รง.506 หรือบันทึกแบบสอบสวนโรคก่อนเลือกโรคเพื่อดู Person · Place · Time')}`;
};

const tracking = () => {
  const cases=readCases(), tasks=readTasks(), contacts=readContacts();
  const done=tasks.filter(task=>task.status==='ควบคุมแล้ว').length;
  const active=tasks.filter(task=>task.status==='กำลังดำเนินการ').length;
  const caseOptions=cases.map((item,index)=>`<option value="${index}">${item.disease || 'ไม่ระบุโรค'} · ${item.patient || item.hn || `เคส ${index+1}`} · ${item.location || item.subdistrict || '-'}</option>`).join('');
  return `${title('ติดตามและควบคุมโรค', 'จัดการเคส บันทึกผู้สัมผัส ติดตามการดำเนินงาน และปิดเคสในหน้าจอเดียว')}<section class="tracking-workflow"><article><b>1. Case Management</b><span>${cases.length} เคสในระบบ</span></article><article><b>2. Contact Tracing</b><span>${contacts.length} ผู้สัมผัสที่บันทึก</span></article><article><b>3. Follow-up</b><span>${active} งานกำลังดำเนินการ</span></article><article><b>4. Case Closure</b><span>${done} งานปิดแล้ว</span></article></section><section class="work-panel"><div class="panel-top"><h2>Case Management · มอบหมายงานสอบสวน / ควบคุมโรค</h2><small>งานจะถูกบันทึกในอุปกรณ์นี้</small></div>${cases.length ? `<form class="form-grid" data-response-task><label>เคสที่รับผิดชอบ<select name="caseIndex" required>${caseOptions}</select></label><label>ผู้รับผิดชอบ<input name="owner" required placeholder="ชื่อเจ้าหน้าที่ / ทีม SRRT" /></label><label>กำหนดเสร็จ<input name="dueDate" type="date" required /></label><label>ระดับความเร่งด่วน<select name="priority"><option>ปกติ</option><option>เฝ้าระวัง</option><option>เร่งด่วน</option></select></label><label>รายละเอียดงาน<input name="note" placeholder="เช่น ตรวจสอบผู้สัมผัสและพื้นที่เสี่ยง" /></label><label>สถานะเริ่มต้น<select name="status"><option>รอรับทราบ</option><option>กำลังดำเนินการ</option></select></label><div class="form-actions"><button class="primary">บันทึกมอบหมายงาน</button></div></form>` : empty('ยังไม่มีเคสสำหรับมอบหมาย', 'เริ่มจากบันทึกข้อมูลในแบบสอบสวนโรคออนไลน์')}</section>${statCards([['งานทั้งหมด', `${tasks.length} งาน`, 'รายการที่มอบหมายแล้ว', 'blue'], ['กำลังดำเนินการ', `${active} งาน`, 'ต้องติดตามโดยผู้รับผิดชอบ', 'orange'], ['ควบคุมแล้ว', `${done} งาน`, 'บันทึกผลเสร็จสิ้นแล้ว', 'green'], ['ผู้สัมผัส', `${contacts.length} ราย`, 'รายการ Contact Tracing', 'purple']])}<section class="work-panel"><div class="panel-top"><h2>Contact Tracing · บันทึกผู้สัมผัส</h2><small>ใช้ประกอบการติดตามผู้สัมผัสของแต่ละเคส</small></div>${cases.length ? `<form class="form-grid" data-contact-tracing><label>เคสอ้างอิง<select name="caseIndex" required>${caseOptions}</select></label><label>ชื่อ-สกุลผู้สัมผัส<input name="contactName" required placeholder="ชื่อผู้สัมผัส" /></label><label>อายุ (ปี)<input name="age" type="number" min="0" max="130" inputmode="numeric" /></label><label>โทรศัพท์<input name="phone" inputmode="tel" placeholder="หมายเลขติดต่อ" /></label><label>ความสัมพันธ์<select name="relationship"><option>สมาชิกครัวเรือน</option><option>เพื่อน / เพื่อนร่วมงาน</option><option>ผู้ดูแล</option><option>สัมผัสในชุมชน</option><option>อื่น ๆ</option></select></label><label>วันที่สัมผัสล่าสุด<input name="exposureDate" type="date" /></label><label>อาการปัจจุบัน<select name="symptom"><option>ไม่มีอาการ</option><option>มีอาการ</option><option>รอติดตาม</option></select></label><label>ผลการติดตาม<select name="followup"><option>รอติดตาม</option><option>ให้คำแนะนำแล้ว</option><option>ส่งตรวจ / ส่งต่อ</option><option>ติดตามครบแล้ว</option></select></label><div class="form-actions"><button class="primary">บันทึกผู้สัมผัส</button></div></form>` : empty('ยังไม่มีเคสอ้างอิง', 'บันทึกเคสในแบบสอบสวนโรคออนไลน์ก่อนเพิ่มผู้สัมผัส')}</section><section class="work-panel"><div class="panel-top"><h2>Follow-up / Case Closure · ตารางติดตามงาน</h2><small>กดปิดงานเมื่อควบคุมเคสแล้ว</small></div>${tasks.length ? `<div class="history-table-wrap"><table><thead><tr><th>เคส</th><th>ผู้รับผิดชอบ</th><th>กำหนดเสร็จ</th><th>ความเร่งด่วน</th><th>สถานะ</th><th>ปิดเมื่อ</th><th>จัดการ</th></tr></thead><tbody>${tasks.map((task,index)=>{ const item=cases[Number(task.caseIndex)] || {}; return `<tr><td><b>${item.disease || 'ไม่ระบุโรค'}</b><br/><small>${item.patient || item.hn || '-'}</small></td><td>${task.owner}</td><td>${task.dueDate ? new Date(task.dueDate).toLocaleDateString('th-TH') : '-'}</td><td><mark class="${task.priority==='เร่งด่วน'?'red':task.priority==='เฝ้าระวัง'?'gold':'blue'}">${task.priority}</mark></td><td><mark class="${task.status==='ควบคุมแล้ว'?'green':'blue'}">${task.status}</mark></td><td>${task.completedAt ? new Date(task.completedAt).toLocaleString('th-TH') : '-'}</td><td>${task.status==='ควบคุมแล้ว' ? '<span class="task-done">✓ ปิดเคสแล้ว</span>' : `<button class="table-action" data-complete-response="${index}">บันทึกควบคุมแล้ว</button>`}</td></tr>`; }).join('')}</tbody></table></div>` : empty('ยังไม่มีงานที่มอบหมาย', 'กรอกแบบฟอร์มด้านบนเพื่อเริ่มติดตามงาน')}</section><section class="work-panel"><div class="panel-top"><h2>ทะเบียนผู้สัมผัส</h2><small>ข้อมูลในอุปกรณ์นี้ · ${contacts.length} รายการ</small></div>${contacts.length ? `<div class="history-table-wrap"><table><thead><tr><th>ผู้สัมผัส</th><th>เคสอ้างอิง</th><th>ความสัมพันธ์</th><th>วันที่สัมผัส</th><th>อาการ</th><th>ผลติดตาม</th><th>จัดการ</th></tr></thead><tbody>${contacts.map((contact,index)=>{ const item=cases[Number(contact.caseIndex)] || {}; const completed=contact.followup==='ติดตามครบแล้ว'; return `<tr><td><b>${contact.contactName}</b><br/><small>${contact.phone || '-'}</small></td><td>${item.disease || 'ไม่ระบุโรค'}<br/><small>${item.patient || item.hn || '-'}</small></td><td>${contact.relationship || '-'}</td><td>${contact.exposureDate ? new Date(contact.exposureDate).toLocaleDateString('th-TH') : '-'}</td><td><mark class="${contact.symptom==='มีอาการ'?'red':'blue'}">${contact.symptom || '-'}</mark></td><td><mark class="${completed?'green':'orange'}">${contact.followup || '-'}</mark></td><td>${completed ? '<span class="task-done">✓ ครบแล้ว</span>' : `<button class="table-action" data-complete-contact="${index}">ติดตามครบแล้ว</button>`}<button class="table-action danger" data-delete-contact="${index}">ลบ</button></td></tr>`; }).join('')}</tbody></table></div>` : empty('ยังไม่มีผู้สัมผัสที่บันทึก', 'เพิ่มข้อมูลจากแบบฟอร์ม Contact Tracing ด้านบน')}</section>`;
};

const epidemiologyTabs = () => {
  const {rows,cases}=values();
  const allRecords=[...rows,...cases];
  const selectedDisease=localStorage.getItem('ndss-epi-disease') || '';
  const diseaseOptions=[...new Set(allRecords.map(item=>item.disease).filter(Boolean))].sort();
  const records=selectedDisease ? allRecords.filter(item=>item.disease===selectedDisease) : allRecords;
  const count=(items,key,fallback='ไม่ระบุ')=>items.reduce((all,item)=>{ const value=item[key] || fallback; all[value]=(all[value]||0)+1; return all; },{});
  const diseases=count(records,'disease');
  const places=records.reduce((all,item)=>{ const value=item.tambon || item.subdistrict || item.district || 'ไม่ระบุพื้นที่'; all[value]=(all[value]||0)+1; return all; },{});
  const ages=records.reduce((all,item)=>{ const age=Number(item.age); const value=!Number.isFinite(age)?'ไม่ระบุ':age<5?'0–4 ปี':age<15?'5–14 ปี':age<60?'15–59 ปี':'60 ปีขึ้นไป'; all[value]=(all[value]||0)+1; return all; },{});
  const sexes=count(records,'sex');
  const nationalities=count(records,'nationality');
  const dated=records.filter(item=>item.onset || item.createdAt || item.importedAt);
  const weeks=dated.reduce((all,item)=>{ const date=new Date(item.onset || item.createdAt || item.importedAt); if(Number.isNaN(date)) return all; const first=new Date(date.getFullYear(),0,1); const label=`${date.getFullYear()+543}-W${String(Math.ceil((((date-first)/86400000)+first.getDay()+1)/7)).padStart(2,'0')}`; all[label]=(all[label]||0)+1; return all; },{});
  const latest=dated.map(item=>new Date(item.onset || item.createdAt || item.importedAt)).filter(date=>!Number.isNaN(date)).sort((a,b)=>b-a)[0];
  const trendYears=[...new Set(dated.map(item=>new Date(item.onset || item.createdAt || item.importedAt).getFullYear()).filter(Number.isFinite))].sort((a,b)=>a-b).slice(-3);
  const trendCounts=trendYears.map(year=>Array.from({length:12},(_,month)=>dated.filter(item=>{ const date=new Date(item.onset || item.createdAt || item.importedAt); return !Number.isNaN(date) && date.getFullYear()===year && date.getMonth()===month; }).length));
  const trendMaximum=Math.max(...trendCounts.flat(),1);
  const weekOfYear=date=>{ const first=new Date(date.getFullYear(),0,1); return Math.ceil((((date-first)/86400000)+first.getDay()+1)/7); };
  const currentYear=latest?.getFullYear();
  const availableYears=[...new Set(dated.map(item=>new Date(item.onset || item.createdAt || item.importedAt).getFullYear()).filter(Number.isFinite))].sort((a,b)=>a-b);
  const baselineYears=currentYear ? availableYears.filter(year=>year<currentYear).slice(-5) : [];
  const weeklyCount=(year,week)=>dated.filter(item=>{ const date=new Date(item.onset || item.createdAt || item.importedAt); return !Number.isNaN(date) && date.getFullYear()===year && weekOfYear(date)===week; }).length;
  const median=values=>{ const sorted=[...values].sort((a,b)=>a-b); const middle=Math.floor(sorted.length/2); return sorted.length%2 ? sorted[middle] : (sorted[middle-1]+sorted[middle])/2; };
  const currentWeekRows=currentYear ? Array.from({length:weekOfYear(latest)},(_,index)=>{ const week=index+1; return {week,current:weeklyCount(currentYear,week),median:baselineYears.length===5 ? median(baselineYears.map(year=>weeklyCount(year,week))) : null}; }).filter(item=>item.current || item.median !== null).slice(-16) : [];
  const timeMaximum=Math.max(...currentWeekRows.flatMap(item=>[item.current,item.median || 0]),1);
  const weeklyEntries=Object.entries(weeks).sort(([left],[right])=>left.localeCompare(right));
  const activeWeeks=weeklyEntries.filter(([,count])=>count>0);
  const curvePeak=activeWeeks.reduce((highest,item)=>item[1]>highest[1]?item:highest,['-',0]);
  const curveDescription=!activeWeeks.length ? 'ยังไม่มีข้อมูลสัปดาห์เริ่มป่วยเพียงพอสำหรับอธิบายการกระจาย' : activeWeeks.length===1 ? `พบการกระจุกตัวของรายงานใน ${activeWeeks[0][0]} จำนวน ${activeWeeks[0][1]} ราย` : `พบรายงานกระจาย ${activeWeeks.length} สัปดาห์ โดยช่วงที่มีจำนวนสูงสุดคือ ${curvePeak[0]} จำนวน ${curvePeak[1]} ราย`;
  const outcomes=records.filter(item=>item.outcome);
  const deaths=outcomes.filter(item=>String(item.outcome).includes('เสียชีวิต')).length;
  const deathCount=outcomes.length ? `${deaths} ราย` : 'ยังไม่มีข้อมูล';
  const cfr=outcomes.length ? `${(deaths / records.length * 100).toFixed(2)} ร้อยละ` : 'ยังไม่มีข้อมูล';
  const tabs=[['situation','สถานการณ์โรค'],['trend','Trend'],['curve','Epidemic Curve'],['person','Person'],['place','Place'],['time','Time']];
  const activeTab=tabs.some(([id])=>id===localStorage.getItem('ndss-epi-tab')) ? localStorage.getItem('ndss-epi-tab') : 'situation';
  const chart=items=>{ const values=Object.entries(items).slice(-16); const maximum=Math.max(...values.map(([,value])=>value),1); return values.length ? `<div class="epi-bars">${values.map(([label,value])=>`<div><b style="height:${Math.max(9,value/maximum*170)}px"></b><small>${label}</small></div>`).join('')}</div>` : empty('ยังไม่มีข้อมูลตามเวลา', 'ต้องมีวันเริ่มป่วยหรือวันบันทึกเพื่อแสดงกราฟ'); };
  const rankedPlaces=()=>{ const entries=Object.entries(places).sort((a,b)=>b[1]-a[1]).slice(0,10); const maximum=entries[0]?.[1] || 1; return `<div class="ranked-list">${entries.map(([name,count],index)=>`<div><b>${index+1}</b><span>${name} (${count} ราย)</span><i><em style="width:${Math.max(8,count/maximum*100)}%"></em></i><strong>${count} ราย</strong></div>`).join('')}</div>`; };
  const situation=records.length ? `${statCards([['จำนวนผู้ป่วยสะสม',`${records.length} ราย`,'หน่วย: ราย','blue'],['อัตราป่วย','ยังไม่มีข้อมูล','ต่อประชากรแสนคน · ต้องมีฐานประชากร','purple'],['ผู้เสียชีวิต / อัตราตาย',deathCount,'ต่อประชากรแสนคน: ยังไม่มีข้อมูล','red'],['อัตราป่วยตาย (CFR)',cfr,'หน่วย: ร้อยละ · ตามผลรักษาที่ระบุ','orange']])}<section class="work-panel"><p class="epi-standard">ข้อมูลจากการเฝ้าระวังโรค จากระบบเฝ้าระวังโรคดิจิทัล (Digital Disease Surveillance; DDS)</p><div class="panel-top"><h2>สถานการณ์โรคตามข้อมูลที่บันทึก</h2><small>หน่วย: ราย</small></div>${ranked(diseases,'โรค')}</section>` : empty('ยังไม่มีข้อมูล', 'นำเข้า รง.506 หรือบันทึกแบบสอบสวนโรคเพื่อแสดงสถานการณ์');
  const trend=trendYears.length ? `<section class="work-panel"><div class="panel-top"><h2>Trend · จำนวนผู้ป่วยรายเดือนย้อนหลัง</h2><small>หน่วย: ราย · ${trendYears.length===3 ? 'เปรียบเทียบ 3 ปีล่าสุดที่มีข้อมูล' : `มีข้อมูล ${trendYears.length} ปี จึงยังเปรียบเทียบไม่ครบ 3 ปี`}</small></div><p class="epi-legend">${trendYears.map((year,index)=>`<i class="epi-year y${index}"></i> ${year+543}`).join('　')}</p><div class="epi-month-chart">${Array.from({length:12},(_,month)=>`<div><span>${trendYears.map((year,index)=>{ const value=trendCounts[index][month]; return `<b class="y${index}" style="height:${value ? Math.max(4,value/trendMaximum*190) : 0}px" title="${year+543}: ${value} ราย"></b>`; }).join('')}</span><small>${month+1}</small></div>`).join('')}</div><p class="analysis-note">กราฟแสดงเฉพาะวันที่เริ่มป่วยหรือวันที่บันทึกที่มีในระบบ ไม่ใช้ข้อมูลตัวอย่างแทนข้อมูลจริง</p></section>` : empty('ยังไม่มีข้อมูลตามเวลา', 'ต้องมีวันเริ่มป่วยหรือวันบันทึกเพื่อแสดงแนวโน้มย้อนหลัง');
  const curve=`<section class="work-panel"><div class="panel-top"><h2>Epidemic Curve · สัปดาห์เริ่มป่วย</h2><small>Histogram · หน่วย: ราย</small></div>${chart(weeks)}<p class="analysis-note"><b>ลักษณะการกระจาย:</b> ${curveDescription}</p><p class="analysis-note">เป็นการพรรณนาตามสัปดาห์เริ่มป่วยเท่านั้น ระบบไม่จำแนก Point-source หรือ Propagated อัตโนมัติ และไม่สรุปสาเหตุหรือยืนยันรูปแบบการระบาด</p></section>`;
  const person=records.length ? `<section class="epi-person-grid"><article class="work-panel"><div class="panel-top"><h2>Person · กลุ่มอายุ</h2><small>หน่วย: ราย</small></div>${ranked(ages,'กลุ่มอายุ')}</article><article class="work-panel"><div class="panel-top"><h2>Person · เพศ</h2><small>หน่วย: ราย</small></div>${ranked(sexes,'เพศ')}</article><article class="work-panel"><div class="panel-top"><h2>Person · สัญชาติ</h2><small>หน่วย: ราย</small></div>${ranked(nationalities,'สัญชาติ')}</article></section>` : empty('ยังไม่มีข้อมูลบุคคล', 'ต้องมีข้อมูลอายุ เพศ หรือสัญชาติจาก รง.506 หรือแบบสอบสวน');
  const place=records.length ? `<section class="work-panel"><div class="panel-top"><h2>Place · การกระจายเชิงพื้นที่</h2><small>เรียงตามจำนวนรายงานภายในขอบเขตข้อมูล</small></div>${rankedPlaces()}<p class="scope-note">ขอบเขตข้อมูลปัจจุบันเป็นตำบล/อำเภอที่มีในรายการเท่านั้น จึงไม่จัดอันดับเทียบข้ามระดับพื้นที่ และยังไม่มีฐานประชากรสำหรับคำนวณอัตราป่วยต่อประชากรแสนคน</p></section>` : empty('ยังไม่มีข้อมูลพื้นที่', 'บันทึกตำบลหรืออำเภอเพื่อแสดงการกระจายเชิงพื้นที่');
  const time=currentWeekRows.length ? `<section class="work-panel"><div class="panel-top"><h2>Time · แนวโน้มรายสัปดาห์</h2><small>ข้อมูล ณ วันที่: ${latest ? latest.toLocaleDateString('th-TH') : 'ยังไม่มีข้อมูล'}</small></div>${baselineYears.length===5 ? `<p class="epi-legend"><i class="time-current"></i> ปี ${currentYear+543} <i class="time-median"></i> ค่ามัธยฐาน 5 ปีย้อนหลัง (${baselineYears.map(year=>year+543).join(', ')})</p><div class="time-median-chart">${currentWeekRows.map(item=>`<div><small>W${String(item.week).padStart(2,'0')}</small><span><b style="width:${item.current/timeMaximum*100}%" title="ปี ${currentYear+543}: ${item.current} ราย"></b><i style="width:${(item.median || 0)/timeMaximum*100}%" title="ค่ามัธยฐาน 5 ปี: ${item.median} ราย"></i></span><em>${item.current} / ${item.median}</em></div>`).join('')}</div><p class="analysis-note">แสดงการเปรียบเทียบเชิงพรรณนาตามข้อมูลที่บันทึกไว้ ไม่สรุปสาเหตุของแนวโน้มที่เพิ่มขึ้นหรือลดลง</p>` : `${chart(weeks)}<p class="analysis-note">มีข้อมูลปีก่อนหน้า ${baselineYears.length} ปี จึงยังไม่สามารถเปรียบเทียบกับค่ามัธยฐาน 5 ปีได้</p>`}</section>` : empty('ยังไม่มีข้อมูลตามเวลา', 'ต้องมีวันเริ่มป่วยหรือวันบันทึกเพื่อแสดงแนวโน้มรายสัปดาห์');
  return `${title('Dashboard ระบาดวิทยา', `Person · Place · Time จากข้อมูลจริงในระบบ · ข้อมูล ณ วันที่: ${latest ? latest.toLocaleDateString('th-TH') : 'ยังไม่มีข้อมูล'}`)}<section class="work-panel analytics-filter epi-disease-filter"><label>เลือกโรคสำหรับวิเคราะห์<select data-epi-disease-filter><option value="">ทุกโรค</option>${diseaseOptions.map(disease=>`<option value="${disease}" ${selectedDisease===disease?'selected':''}>${disease}</option>`).join('')}</select></label><small>${selectedDisease ? `กำลังแสดงเฉพาะ: ${selectedDisease}` : 'กำลังแสดงข้อมูลทุกโรค'}</small></section><section class="epi-dashboard"><div class="epi-tabs" role="tablist">${tabs.map(([id,label])=>`<button type="button" class="${id===activeTab?'active':''}" data-epi-tab="${id}">${label}</button>`).join('')}</div><div class="epi-pane ${activeTab==='situation'?'active':''}" data-epi-pane="situation" ${activeTab==='situation'?'':'hidden'}>${situation}</div><div class="epi-pane ${activeTab==='trend'?'active':''}" data-epi-pane="trend" ${activeTab==='trend'?'':'hidden'}>${trend}</div><div class="epi-pane ${activeTab==='curve'?'active':''}" data-epi-pane="curve" ${activeTab==='curve'?'':'hidden'}>${curve}</div><div class="epi-pane ${activeTab==='person'?'active':''}" data-epi-pane="person" ${activeTab==='person'?'':'hidden'}>${person}</div><div class="epi-pane ${activeTab==='place'?'active':''}" data-epi-pane="place" ${activeTab==='place'?'':'hidden'}>${place}</div><div class="epi-pane ${activeTab==='time'?'active':''}" data-epi-pane="time" ${activeTab==='time'?'':'hidden'}>${time}</div></section>`;
};

const lab = () => {
  const results=readLab();
  const positive=results.filter(item=>item.result==='Positive').length;
  const pending=results.filter(item=>item.result==='รอตรวจสอบ').length;
  const cases=readCases();
  return `${title('รายงานห้องปฏิบัติการ', 'บันทึกผลตรวจ ติดตามรายการรอตรวจสอบ และเชื่อมโยงกับเคสสอบสวนที่มีในอุปกรณ์นี้')}<section class="work-panel"><div class="panel-top"><h2>เพิ่มผลตรวจ</h2><small>ผลตรวจจะบันทึกในเบราว์เซอร์นี้</small></div><form class="form-grid" data-lab-result><label>เลขที่สิ่งส่งตรวจ<input name="specimenNo" required placeholder="เช่น LAB-2569-0001" /></label><label>เคสที่เกี่ยวข้อง<select name="caseIndex"><option value="">ไม่ระบุ / ยังไม่ผูกเคส</option>${cases.map((item,index)=>`<option value="${index}">${item.disease || 'ไม่ระบุโรค'} · ${item.patient || item.hn || `เคส ${index+1}`}</option>`).join('')}</select></label><label>ประเภทการตรวจ<select name="test" required><option>Influenza A</option><option>Influenza B</option><option>COVID-19</option><option>Dengue NS1 Ag</option><option>Dengue IgG</option><option>Dengue IgM</option><option>AFB Smear</option><option>GeneXpert MTB/RIF</option><option>อื่น ๆ</option></select></label><label>วันที่รับสิ่งส่งตรวจ<input name="receivedAt" type="date" required /></label><label>ผลตรวจ<select name="result" required><option>รอตรวจสอบ</option><option>Positive</option><option>Negative</option><option>ไม่สามารถทดสอบได้</option></select></label><label>รายละเอียดเพิ่มเติม<input name="note" placeholder="เช่น ชนิดสิ่งส่งตรวจ / ข้อสังเกต" /></label><div class="form-actions"><button class="primary">บันทึกผลตรวจ</button></div></form></section>${statCards([['ผลตรวจทั้งหมด', `${results.length} รายการ`, 'ที่บันทึกในระบบนี้', 'blue'], ['ผล Positive', `${positive} รายการ`, 'ต้องตรวจทานตามแนวทาง', 'red'], ['รอตรวจสอบ', `${pending} รายการ`, 'ยังไม่ลงผลสุดท้าย', 'orange'], ['เชื่อมโยงเคส', `${results.filter(item=>item.caseIndex!=='').length} รายการ`, 'อ้างอิงแบบสอบสวน', 'green']])}<section class="work-panel"><div class="panel-top"><h2>ผลตรวจล่าสุด</h2><input class="table-search" data-lab-search placeholder="ค้นหาเลขสิ่งส่งตรวจ, ประเภท, ผลตรวจ" /></div>${results.length ? `<div class="history-table-wrap"><table><thead><tr><th>วันที่รับ</th><th>เลขสิ่งส่งตรวจ</th><th>การตรวจ</th><th>ผล</th><th>เคสอ้างอิง</th><th>จัดการ</th></tr></thead><tbody data-lab-rows>${results.map((item,index)=>{ const linked=cases[Number(item.caseIndex)] || {}; const tone=item.result==='Positive'?'red':item.result==='Negative'?'green':item.result==='รอตรวจสอบ'?'orange':'blue'; return `<tr><td>${item.receivedAt ? new Date(item.receivedAt).toLocaleDateString('th-TH') : '-'}</td><td>${item.specimenNo}</td><td>${item.test}</td><td><mark class="${tone}">${item.result}</mark></td><td>${linked.patient || linked.hn || '-'}</td><td><button class="table-action danger" data-delete-lab="${index}">ลบ</button></td></tr>`; }).join('')}</tbody></table></div>` : empty('ยังไม่มีผลตรวจ', 'เพิ่มผลตรวจจากแบบฟอร์มด้านบนเพื่อเริ่มติดตาม')}</section>`;
};

const alerts = () => {
  const signals=clusterSignals();
  const tasks=readTasks();
  const state=readAlertState();
  const today=new Date().toISOString().slice(0,10);
  const overdue=tasks.filter(task=>task.status!=='ควบคุมแล้ว' && task.dueDate && task.dueDate<today);
  const waiting=tasks.filter(task=>task.status==='รอรับทราบ');
  const labs=readLab();
  const positiveLabs=labs.filter(item=>item.result==='Positive');
  const contacts=readContacts();
  const symptomaticContacts=contacts.filter(item=>item.symptom==='มีอาการ' && item.followup!=='ติดตามครบแล้ว');
  const records=read506();
  const incomplete=records.filter(item=>!item.disease || !(item.tambon || item.district) || !item.onset);
  const diseaseTotals=records.reduce((all,item)=>{ const disease=item.disease || 'ไม่ระบุโรค'; all[disease]=(all[disease]||0)+1; return all; },{});
  const threshold=Object.entries(diseaseTotals).filter(([,count])=>count>=5);
  const items=[...threshold.map(([disease,count])=>({id:`threshold-${disease}`,tone:'orange',title:`Threshold: ${disease}`,detail:`พบข้อมูลสะสม ${count} รายในขอบเขตข้อมูลปัจจุบัน`,view:'report506'})),...signals.map(signal=>({id:`cluster-${signal.disease}-${signal.area}-${signal.period}`,tone:'red',title:`Cluster: ${signal.disease}`,detail:`${signal.area} · ${signal.period} · ${signal.count} ราย`,view:'clusters'})),...overdue.map((task,index)=>({id:`outbreak-${task.createdAt || index}`,tone:'orange',title:'Outbreak: งานติดตามเกินกำหนด',detail:`ผู้รับผิดชอบ: ${task.owner} · กำหนด ${new Date(task.dueDate).toLocaleDateString('th-TH')}`,view:'queue'})),...positiveLabs.map((item,index)=>({id:`lab-${item.specimenNo || index}`,tone:'red',title:`Lab Alert: ${item.test}`,detail:`ผล Positive · ${item.specimenNo || 'ไม่ระบุเลขสิ่งส่งตรวจ'}`,view:'lab'})),...symptomaticContacts.map((item,index)=>({id:`contact-${item.createdAt || index}`,tone:'red',title:'Contact Alert: ผู้สัมผัสมีอาการ',detail:`${item.contactName || 'ไม่ระบุชื่อ'} · ${item.relationship || 'ไม่ระบุความสัมพันธ์'} · ต้องติดตาม`,view:'tracking'})),...incomplete.map((item,index)=>({id:`quality-${item.importedAt || index}`,tone:'blue',title:'Data Quality Alert',detail:`รายการ รง.506 ขาด ${!item.disease?'โรค ':''}${!(item.tambon || item.district)?'พื้นที่ ':''}${!item.onset?'วันเริ่มป่วย':''}`.trim(),view:'import506'})),...waiting.map((task,index)=>({id:`waiting-${task.createdAt || index}`,tone:'blue',title:'งานรอรับทราบ',detail:`ผู้รับผิดชอบ: ${task.owner} · ${task.priority}`,view:'tracking'}))];
  items.sort((left,right)=>Number(Boolean(state[left.id]))-Number(Boolean(state[right.id])));
  const active=items.filter(item=>!state[item.id]);
  const acknowledged=items.length-active.length;
  return `${title('ระบบแจ้งเตือน', 'สรุปสัญญาณจากข้อมูลที่บันทึก เพื่อให้ทีมตรวจสอบและดำเนินการตามบทบาท')}<section class="alert-notice"><b>หลักการแจ้งเตือน</b><span>ระบบแสดงสัญญาณจากเกณฑ์ข้อมูลและกำหนดงาน ไม่ยืนยันเหตุการณ์หรือสาเหตุแทนผู้ปฏิบัติงาน</span></section>${statCards([['Threshold', `${threshold.length} รายการ`, 'โรคที่มีข้อมูลตั้งแต่ 5 ราย', 'orange'], ['Cluster', `${signals.length} กลุ่ม`, 'ตามเกณฑ์คัดกรอง', 'red'], ['Outbreak', `${overdue.length} งาน`, 'งานติดตามเกินกำหนด', 'purple'], ['Lab Alert', `${positiveLabs.length} รายการ`, 'ผล Positive ที่บันทึก', 'red'], ['Data Quality Alert', `${incomplete.length} รายการ`, 'ข้อมูล รง.506 ที่ยังไม่ครบ', 'blue']])}<section class="work-panel"><div class="panel-top"><h2>รายการแจ้งเตือน</h2><button class="primary" data-view="line-notify">เตรียมส่ง LINE OA</button></div>${items.length ? `<div class="alert-feed">${items.map(item=>`<article class="${item.tone}${state[item.id]?' acknowledged':''}"><i></i><div><b>${item.title}</b><span>${item.detail}${state[item.id] ? ` · รับทราบ ${new Date(state[item.id]).toLocaleString('th-TH')}` : ''}</span></div>${state[item.id] ? '<span class="task-done">✓ รับทราบแล้ว</span>' : `<button class="table-action" data-ack-alert="${item.id}">รับทราบ</button>`}<button class="table-action" data-view="${item.view}">เปิดดู</button></article>`).join('')}</div>` : empty('ยังไม่มีรายการแจ้งเตือน', 'เมื่อข้อมูลเข้าเกณฑ์ Threshold, Cluster, Outbreak, Lab หรือ Data Quality ระบบจะแสดงในหน้านี้')}</section>`;
};

const audit = () => { const entries=readAudit(); return `${title('บันทึกกิจกรรมระบบ', 'ประวัติเหตุการณ์สำคัญสำหรับตรวจสอบการทำงานของระบบ โดยไม่แสดงข้อมูลผู้ป่วยรายบุคคล')}<section class="work-panel"><div class="panel-top"><h2>กิจกรรมล่าสุด</h2><div class="panel-tools"><input class="table-search" data-audit-search placeholder="ค้นหากิจกรรมหรือรายละเอียด" /><button class="secondary" data-clear-audit>ล้างประวัติในอุปกรณ์นี้</button></div></div>${entries.length ? `<div class="audit-list" data-audit-list>${entries.slice(0,100).map(entry=>`<article data-audit-row><i></i><div><b>${entry.action}</b><span>${entry.detail}</span></div><time>${new Date(entry.at).toLocaleString('th-TH')}</time></article>`).join('')}</div><p class="audit-empty" data-audit-empty hidden>ไม่พบกิจกรรมที่ตรงกับคำค้นหา</p>` : empty('ยังไม่มีบันทึกกิจกรรม', 'ระบบจะบันทึกการนำเข้าข้อมูล การบันทึกเคส และการมอบหมาย/ปิดงานจากอุปกรณ์นี้')}</section>`; };

const report506 = () => {
  const { rows } = values();
  const diseases=[...new Set(rows.map(row=>row.disease).filter(Boolean))].sort();
  const areas=[...new Set(rows.map(row=>row.tambon || row.district).filter(Boolean))].sort();
  const selectedDisease=localStorage.getItem('ndss-506-report-disease') || '';
  const selectedArea=localStorage.getItem('ndss-506-report-area') || '';
  const filtered=rows.filter(row=>(!selectedDisease || row.disease===selectedDisease) && (!selectedArea || (row.tambon || row.district)===selectedArea));
  const dated=filtered.map(row=>new Date(row.onset)).filter(date=>!Number.isNaN(date)).sort((a,b)=>b-a)[0];
  return `${title('รายงาน รง.506', 'ตรวจสอบรายการนำเข้าและสร้างรายงานตามขอบเขตข้อมูลที่เลือก', '<div class="command-actions no-print"><button class="secondary" data-export-506-csv>⇩ ดาวน์โหลด CSV</button><button class="primary" data-print-command-report>▣ พิมพ์รายงาน</button></div>')}${statCards([['รายการในรายงาน', `${filtered.length} ราย`, 'ตามตัวกรองที่เลือก', 'blue'], ['โรคที่พบ', `${new Set(filtered.map(row=>row.disease).filter(Boolean)).size} โรค`, 'จากข้อมูลที่เลือก', 'purple'], ['พื้นที่ที่พบ', `${new Set(filtered.map(row=>row.tambon || row.district).filter(Boolean)).size} พื้นที่`, 'ตำบลหรืออำเภอตามข้อมูล', 'green'], ['ข้อมูลล่าสุด', dated ? dated.toLocaleDateString('th-TH') : 'ยังไม่มีข้อมูล', 'อ้างอิงวันเริ่มป่วย', 'orange']])}<section class="work-panel no-print"><div class="panel-top"><h2>คัดกรองข้อมูลรายงาน</h2><small>การกรองไม่แก้ไขข้อมูลต้นฉบับ</small></div><div class="form-grid"><label>โรค<select data-506-report-disease><option value="">ทุกโรค</option>${diseases.map(disease=>`<option value="${disease}" ${selectedDisease===disease?'selected':''}>${disease}</option>`).join('')}</select></label><label>พื้นที่<select data-506-report-area><option value="">ทุกพื้นที่</option>${areas.map(area=>`<option value="${area}" ${selectedArea===area?'selected':''}>${area}</option>`).join('')}</select></label><label>ค้นหารายการ<input data-506-report-search placeholder="ชื่อผู้ป่วย, โรค, ตำบล หรืออำเภอ" /></label></div></section><section class="work-panel"><div class="panel-top"><h2>รายการ รง.506</h2><small>แสดง ${filtered.length} ราย · หน่วย: ราย</small></div>${filtered.length ? `<div class="history-table-wrap"><table><thead><tr><th>วันที่เริ่มป่วย</th><th>โรค</th><th>ผู้ป่วย</th><th>อายุ</th><th>เพศ</th><th>ตำบล / อำเภอ</th></tr></thead><tbody data-506-report-rows>${filtered.map(row=>`<tr><td>${row.onset ? new Date(row.onset).toLocaleDateString('th-TH') : '-'}</td><td>${row.disease || '-'}</td><td>${row.patient || '-'}</td><td>${row.age || '-'}</td><td>${row.sex || '-'}</td><td>${row.tambon || '-'}${row.district ? ` / ${row.district}` : ''}</td></tr>`).join('')}</tbody></table></div><p class="audit-empty" data-506-report-empty hidden>ไม่พบรายการที่ตรงกับคำค้นหา</p>` : empty('ยังไม่มีข้อมูลตามเงื่อนไขที่เลือก', 'เลือกตัวกรองอื่น หรือนำเข้าข้อมูล รง.506 เพื่อเริ่มสร้างรายงาน')}</section>`;
};

const exporter = () => {
  const rows=read506(), cases=readCases(), labs=readLab(), tasks=readTasks();
  return `${title('ส่งออกรายงาน', 'เลือกชุดข้อมูลเพื่อดาวน์โหลดเป็น CSV สำหรับตรวจทานหรือใช้งานต่อ โดยการส่งออกจะเกิดขึ้นในอุปกรณ์นี้')}<section class="work-panel"><div class="panel-top"><h2>ตั้งค่าการส่งออก</h2><small>ข้อมูลผู้ป่วยเป็นข้อมูลส่วนบุคคล ควรส่งออกและจัดเก็บตามสิทธิ์ของหน่วยงาน</small></div><form class="form-grid" data-command-export><label>ชุดข้อมูล<select name="dataset"><option value="506">ข้อมูล รง.506</option><option value="investigation">แบบสอบสวนโรค</option><option value="lab">ผลห้องปฏิบัติการ</option><option value="tasks">งานติดตามและควบคุมโรค</option></select></label><label>รูปแบบไฟล์<input value="CSV (UTF-8)" disabled /></label><label>ชื่อไฟล์ (ไม่บังคับ)<input name="filename" placeholder="เช่น รายงาน-ประจำเดือน" /></label><div class="form-actions"><button class="primary">⇩ ดาวน์โหลด CSV</button></div></form></section>${statCards([['ข้อมูล รง.506', `${rows.length} ราย`, 'พร้อมส่งออก', 'blue'], ['แบบสอบสวน', `${cases.length} ราย`, 'พร้อมส่งออก', 'green'], ['ผล LAB', `${labs.length} รายการ`, 'พร้อมส่งออก', 'purple'], ['งานติดตาม', `${tasks.length} งาน`, 'พร้อมส่งออก', 'orange']])}<section class="work-panel"><h2>คำแนะนำก่อนส่งออก</h2><ul class="command-list"><li>ตรวจสอบความครบถ้วนของข้อมูลและขอบเขตพื้นที่ก่อนเผยแพร่รายงาน</li><li>ไม่ควรส่งต่อไฟล์ที่มีชื่อ เลขประจำตัว หรือพิกัดผู้ป่วยให้ผู้ที่ไม่มีสิทธิ์</li><li>ไฟล์ CSV ใช้รหัส UTF-8 เพื่อรองรับข้อความภาษาไทย</li></ul></section>`;
};

const reports = () => {
  const { rows, cases, byDisease } = values();
  const issuedAt=new Date().toLocaleString('th-TH');
  const rowsByDisease=Object.entries(byDisease).sort((a,b)=>b[1]-a[1]);
  return `${title('สรุปผลการสอบสวนและรายงาน', 'สร้างตารางสรุปตามข้อมูลที่บันทึกไว้ โดยไม่ใช้ข้อมูลจำลอง', '<div class="command-actions no-print"><button class="secondary" data-export-506-csv>⇩ CSV</button><button class="primary" data-print-command-report>▣ พิมพ์ / บันทึก PDF</button></div>')}${statCards([['ข้อมูล รง.506', `${rows.length} ราย`, 'รายการจากการนำเข้า', 'blue'], ['แบบสอบสวน', `${cases.length} ราย`, 'รายการที่บันทึก', 'green'], ['โรคที่สรุปได้', `${Object.keys(byDisease).length} โรค`, 'จากคอลัมน์โรค', 'purple']])}<section class="work-panel printable-command-report command-report-sheet"><header class="command-report-header"><img src="./public/assets/naradhiwas-hospital-logo.jpg" alt="โลโก้โรงพยาบาล" /><div><b>โรงพยาบาลนราธิวาสราชนครินทร์</b><span>Naradhiwas Rajanagarindra Hospital</span><h2>รายงานสรุปสถานการณ์และผลการสอบสวนโรค</h2></div><small>จัดทำ ณ<br/>${issuedAt}</small></header><div class="command-report-summary"><b>ข้อมูล รง.506 ${rows.length} ราย</b><b>แบบสอบสวน ${cases.length} ราย</b><b>โรคที่พบ ${rowsByDisease.length} โรค</b></div><div class="panel-top"><h2>สรุปตามโรค</h2><small>หน่วย: ราย</small></div>${rowsByDisease.length ? `<table><thead><tr><th>ลำดับ</th><th>โรค</th><th>จำนวนผู้ป่วย</th><th>แบบสอบสวนที่บันทึก</th></tr></thead><tbody>${rowsByDisease.map(([d,count],index) => `<tr><td>${index+1}</td><td>${d}</td><td>${count} ราย</td><td>${cases.filter(x=>x.disease===d).length} ราย</td></tr>`).join('')}</tbody></table>` : empty('ยังไม่มีข้อมูลรายงาน', 'นำเข้าข้อมูล รง.506 ก่อนสร้างรายงานสรุป')}<footer class="command-report-footer">NDSS · เอกสารสรุปจากข้อมูลที่บันทึกในระบบ · โปรดตรวจทานก่อนเผยแพร่</footer></section>`;
};

const reportsSummary = () => {
  const { rows, cases, byDisease }=values();
  const tasks=readTasks();
  const diseases=Object.entries(byDisease).sort((a,b)=>b[1]-a[1]);
  const completed=tasks.filter(task=>task.status==='ควบคุมแล้ว').length;
  const dataRows=diseases.map(([disease,count])=>{ const investigated=cases.filter(item=>item.disease===disease).length; const done=tasks.filter(task=>{ const linked=cases[Number(task.caseIndex)]; return linked?.disease===disease && task.status==='ควบคุมแล้ว'; }).length; const totalTasks=tasks.filter(task=>cases[Number(task.caseIndex)]?.disease===disease).length; const coverage=count ? Math.round(investigated/count*100) : 0; return {disease,count,investigated,done,totalTasks,coverage}; });
  return `${title('สรุปผลการสอบสวนโรค', 'สรุปข้อมูลรายโรคจาก รง.506 แบบสอบสวน และงานติดตามในระบบ', '<div class="command-actions"><button class="secondary" data-export-506-csv>⇩ CSV รง.506</button><button class="primary" data-print-summary>▣ พิมพ์รายงาน / PDF</button></div>')}<section class="report-filter-panel"><label>ค้นหาโรค<input class="table-search" data-report-search placeholder="พิมพ์ชื่อโรค เช่น ไข้เลือดออก" /></label><label>แสดงเหตุการณ์<select data-report-status><option value="all">ทุกสถานะ</option><option value="pending">ยังมีงานค้าง</option><option value="done">ดำเนินการครบแล้ว</option></select></label><small>ผลการค้นหาใช้ข้อมูลที่บันทึกในอุปกรณ์นี้</small></section>${statCards([['ผู้ป่วยที่ต้องสอบสวน', `${rows.length} ราย`, 'ข้อมูลจาก รง.506', 'blue'], ['จำนวนโรค', `${diseases.length} โรค`, 'จากชื่อโรคที่บันทึก', 'purple'], ['สอบสวนแล้ว', `${cases.length} ราย`, 'จากแบบสอบสวนออนไลน์', 'green'], ['งานติดตามคงค้าง', `${Math.max(0,tasks.length-completed)} งาน`, 'ยังไม่ปิดสถานะ', 'orange']])}<section class="work-panel printable-command-report report-summary-sheet"><div class="panel-top"><div><h2>▤ สรุปผลการสอบสวนโรค · ทั้งพื้นที่</h2><small>เรียงตามจำนวนผู้ป่วยและความคืบหน้าของงาน</small></div><span class="report-disease-count">${diseases.length} โรค</span></div>${dataRows.length ? `<div class="history-table-wrap"><table class="report-summary-table"><thead><tr><th>โรค</th><th>ผู้ป่วยทั้งหมด</th><th>แบบสอบสวน</th><th>ติดตามเสร็จ</th><th>ยังไม่สอบสวน/ติดตาม</th><th>ความคืบหน้า</th><th>จัดการ</th></tr></thead><tbody data-report-rows>${dataRows.map(item=>{ const pending=Math.max(0,item.count-item.investigated)+Math.max(0,item.totalTasks-item.done); const state=pending?'pending':'done'; return `<tr data-report-status="${state}"><td><b>${item.disease}</b></td><td>${item.count}</td><td><mark class="green">${item.investigated}</mark></td><td><mark class="green">${item.done}</mark></td><td><mark class="${pending?'gold':'green'}">${pending}</mark></td><td><span class="report-progress"><i style="width:${Math.min(100,item.coverage)}%"></i><b>${item.coverage}%</b></span></td><td><button class="table-action" data-view="investigation">ดูรายการ</button></td></tr>`; }).join('')}</tbody></table></div>` : empty('ยังไม่มีข้อมูลสำหรับสรุป', 'นำเข้าข้อมูล รง.506 และบันทึกแบบสอบสวนเพื่อแสดงรายงาน')}<p class="scope-note">ความคืบหน้าเทียบจำนวนแบบสอบสวนที่บันทึกกับจำนวนผู้ป่วยในข้อมูล รง.506 ไม่ใช่การประเมินคุณภาพทางระบาดวิทยา</p></section>`;
};

const reportsEvent = () => {
  const { rows, cases }=values();
  const tasks=readTasks();
  const source=cases.length ? cases.map((item,index)=>({...item,caseIndex:index,source:'แบบสอบสวน'})) : rows.map((item,index)=>({...item,caseIndex:index,source:'รง.506'}));
  const weekOf=item=>{ const date=new Date(item.onset || item.createdAt || item.importedAt); if(Number.isNaN(date)) return 'ไม่ระบุสัปดาห์'; const first=new Date(date.getFullYear(),0,1); const week=Math.ceil((((date-first)/86400000)+first.getDay()+1)/7); return `${date.getFullYear()+543}-W${String(week).padStart(2,'0')}`; };
  const events=Object.values(source.reduce((all,item)=>{ const area=item.subdistrict || item.tambon || item.district || item.location || 'ไม่ระบุพื้นที่'; const disease=item.disease || 'ไม่ระบุโรค'; const week=weekOf(item); const key=`${disease}|${area}|${week}`; all[key]=all[key] || {id:`EVT-${String(Object.keys(all).length+1).padStart(3,'0')}`,disease,area,week,items:[]}; all[key].items.push(item); return all; },{})).map(group=>{ const completed=group.items.filter(item=>tasks.some(task=>Number(task.caseIndex)===item.caseIndex && task.status==='ควบคุมแล้ว')).length; return {...group,completed,pending:group.items.length-completed}; }).sort((a,b)=>b.pending-a.pending || b.items.length-a.items.length);
  const completedEvents=events.filter(item=>item.pending===0).length;
  return `${title('รายงานผลสอบสวน (ราย/Event)', 'จัดกลุ่มรายการตามโรค พื้นที่ และสัปดาห์ เพื่อเตรียมตรวจทานผลสอบสวนและพิมพ์รายงาน', '<div class="command-actions no-print"><button class="secondary" data-export-506-csv>⇩ CSV</button><button class="primary" data-print-command-report>▣ พิมพ์รายงาน / PDF</button></div>')}<section class="queue-note"><b>ขอบเขตการจัดกลุ่ม</b><span>ระบบจัดกลุ่มจากข้อมูลที่บันทึกในอุปกรณ์นี้ตามโรค พื้นที่ และสัปดาห์เริ่มป่วย เพื่อช่วยติดตามงาน ไม่ใช่การยืนยันเหตุการณ์ระบาด</span></section><section class="report-filter-panel no-print"><label>ค้นหารายงาน / Event<input class="table-search" data-event-report-search placeholder="พิมพ์โรค พื้นที่ หรือรหัส Event" /></label><label>สถานะ<select data-event-report-status><option value="all">ทุกสถานะ</option><option value="pending">ยังไม่สอบสวนครบ</option><option value="done">ดำเนินการแล้ว</option></select></label><small>กด “เปิดแบบสอบสวน” เพื่อบันทึกหรือแก้ไขรายละเอียดเคสรายบุคคล</small></section>${statCards([['รายการผู้ป่วย', `${source.length} ราย`, cases.length?'จากแบบสอบสวนออนไลน์':'จากข้อมูล รง.506', 'blue'], ['เหตุการณ์ที่จัดกลุ่ม', `${events.length} Event`, 'โรค · พื้นที่ · สัปดาห์', 'purple'], ['สอบสวนครบแล้ว', `${completedEvents} Event`, 'ตามสถานะงานติดตาม', 'green'], ['ยังต้องติดตาม', `${events.reduce((sum,item)=>sum+item.pending,0)} ราย`, 'ไม่ใช่การยืนยันความเร่งด่วน', 'orange']])}<section class="work-panel printable-command-report command-report-sheet"><header class="command-report-header"><img src="./public/assets/naradhiwas-hospital-logo.jpg" alt="โลโก้โรงพยาบาล" /><div><b>โรงพยาบาลนราธิวาสราชนครินทร์</b><span>Naradhiwas Rajanagarindra Hospital</span><h2>รายงานผลสอบสวนโรค ราย/Event</h2></div><small>ข้อมูล ณ<br/>${new Date().toLocaleString('th-TH')}</small></header><div class="panel-top"><div><h2>รายการ Event ที่จัดกลุ่ม</h2><small>ทั้งหมด ${events.length} Event · หน่วย: ราย</small></div></div>${events.length ? `<div class="history-table-wrap"><table class="event-report-table"><thead><tr><th>Event</th><th>โรค / พื้นที่</th><th>ช่วงเวลา</th><th>ราย</th><th>สอบสวนแล้ว</th><th>สถานะ</th><th class="no-print">จัดการ</th></tr></thead><tbody data-event-report-rows>${events.map(item=>`<tr data-event-report-status="${item.pending?'pending':'done'}"><td><b>${item.id}</b></td><td><b>${item.disease}</b><br/><small>${item.area}</small></td><td>${item.week}</td><td>${item.items.length}</td><td><mark class="green">${item.completed}</mark></td><td><mark class="${item.pending?'gold':'green'}">${item.pending?`รอติดตาม ${item.pending} ราย`:'ดำเนินการแล้ว'}</mark></td><td class="no-print"><button class="table-action" data-view="investigation">เปิดแบบสอบสวน</button></td></tr>`).join('')}</tbody></table></div>` : empty('ยังไม่มีข้อมูลสำหรับจัดกลุ่ม Event', 'บันทึกแบบสอบสวนโรคหรือนำเข้าข้อมูล รง.506 เพื่อสร้างรายการรายงาน')}<footer class="command-report-footer">NDSS · การจัดกลุ่มเพื่อช่วยติดตามงานจากข้อมูลที่บันทึกในระบบ · โปรดตรวจทานก่อนเผยแพร่</footer></section>`;
};

const aiBrief = () => `${title('AI ช่วยสรุปสถานการณ์', 'สร้างร่างข้อความเชิงพรรณนาจากข้อมูลในระบบ เพื่อให้เจ้าหน้าที่ตรวจทานก่อนเผยแพร่')}<section class="work-panel ai-panel"><div class="form-grid"><label>ช่วงข้อมูล<select data-ai-period><option>ข้อมูลทั้งหมดที่นำเข้า</option><option>เดือนปัจจุบัน</option></select></label><label>รูปแบบข้อความ<select data-ai-tone><option>รายงานสถานการณ์</option><option>สรุปสำหรับทีม SRRT</option></select></label><label>ขอบเขตพื้นที่<select data-ai-area><option>ทุกพื้นที่</option><option>เฉพาะข้อมูลที่มีตำบล</option></select></label></div><div class="form-actions"><button class="primary" data-generate-ai-brief>✦ สร้างร่างบทวิเคราะห์</button></div><article class="ai-output" data-ai-output><h2>ร่างบทวิเคราะห์</h2><p>เลือกเงื่อนไขแล้วกด “สร้างร่างบทวิเคราะห์” ระบบจะแสดงข้อความเชิงพรรณนาจากข้อมูลที่มี โดยไม่สรุปสาเหตุเกินข้อมูล</p></article></section><section class="work-panel"><h2>หลักการใช้งาน</h2><ul class="command-list"><li>ผลลัพธ์เป็นร่างสำหรับตรวจทาน ไม่ใช่ข้อสรุปทางระบาดวิทยาอัตโนมัติ</li><li>หากไม่มีข้อมูล ระบบจะแสดง “ยังไม่มีข้อมูล” โดยไม่สร้างข้อมูลตัวอย่าง</li><li>การเชื่อมต่อ AI ภายนอกต้องกำหนดคีย์และนโยบายข้อมูลในส่วนผู้ดูแลก่อนใช้งานจริง</li></ul></section>`;
const aiReportCenter = () => {
  const reports=readAiReports();
  return `${title('AI ช่วยสรุปรายงานสถานการณ์', 'สร้างร่างรายงานจากข้อมูลจริงในระบบ และเก็บฉบับที่ตรวจทานแล้วไว้ในอุปกรณ์นี้')}<section class="work-panel ai-panel"><div class="report-filter-panel"><label>ช่วงข้อมูล<select data-ai-period><option>เดือนปัจจุบัน</option><option>ข้อมูลทั้งหมดที่นำเข้า</option></select></label><label>รูปแบบการวิเคราะห์<select data-ai-tone><option>รายงานสถานการณ์</option><option>สรุปสำหรับทีม SRRT</option></select></label><label>ขอบเขตพื้นที่<select data-ai-area><option>ทุกพื้นที่</option><option>เฉพาะข้อมูลที่มีตำบล</option></select></label></div><div class="ai-report-actions"><button class="primary" data-generate-ai-brief>✦ สร้างรายงานสถานการณ์</button><button class="secondary" data-save-ai-brief>▣ บันทึก (ร่าง)</button><button class="secondary" data-print-ai-brief>▥ พิมพ์ / PDF</button></div><article class="ai-output ai-report-output" data-ai-output><h2>ร่างรายงานสถานการณ์</h2><p>เลือกเงื่อนไขและกด “สร้างรายงานสถานการณ์” ระบบจะสรุปเชิงพรรณนาจากข้อมูลที่มี โดยไม่สรุปสาเหตุเกินข้อมูล</p></article></section><section class="work-panel"><div class="panel-top"><div><h2>รายการรายงานสถานการณ์</h2><small>ฉบับที่บันทึกไว้ในอุปกรณ์นี้</small></div><span class="report-disease-count">${reports.length} ฉบับ</span></div>${reports.length ? `<div class="history-table-wrap"><table><thead><tr><th>วันที่บันทึก</th><th>ช่วงข้อมูล</th><th>รูปแบบ</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${reports.map((report,index)=>`<tr><td>${new Date(report.createdAt).toLocaleString('th-TH')}</td><td>${report.period}</td><td>${report.tone}</td><td><mark class="green">บันทึกร่างแล้ว</mark></td><td><button class="table-action" data-open-ai-report="${index}">เปิดรายงาน</button><button class="table-action danger" data-delete-ai-report="${index}">ลบ</button></td></tr>`).join('')}</tbody></table></div>` : empty('ยังไม่มีรายงานที่บันทึก', 'สร้างร่างและตรวจทานก่อนกดบันทึกรายงาน')}</section><section class="work-panel no-print"><h2>หลักการใช้งาน</h2><ul class="command-list"><li>ผลลัพธ์เป็นร่างสำหรับตรวจทาน ไม่ใช่ข้อสรุปทางระบาดวิทยาอัตโนมัติ</li><li>หากไม่มีข้อมูลตามขอบเขต ระบบจะแสดง “ยังไม่มีข้อมูล” โดยไม่สร้างข้อมูลตัวอย่าง</li><li>การเชื่อมต่อ AI ภายนอกต้องกำหนดคีย์และนโยบายข้อมูลในส่วนผู้ดูแลก่อนใช้งานจริง</li></ul></section>`;
};
const executive = () => {
  const {rows,cases,byDisease,byTambon}=values();
  const tasks=readTasks();
  const overdue=tasks.filter(task=>task.dueDate && new Date(`${task.dueDate}T23:59:59`)<new Date() && task.status!=='ควบคุมแล้ว').length;
  const completed=tasks.filter(task=>task.status==='ควบคุมแล้ว').length;
  const top=Object.entries(byDisease).sort((a,b)=>b[1]-a[1])[0];
  return `${title('รายงานผู้บริหาร', 'ภาพรวมเพื่อสนับสนุนการติดตามสถานการณ์ การมอบหมายงาน และการตัดสินใจจากข้อมูลที่บันทึกจริง', '<div class="command-actions"><button class="secondary" data-view="area-map">🗺️ ดูแผนที่</button><button class="primary" data-print-summary>▣ พิมพ์รายงาน / PDF</button></div>')}${statCards([['ข้อมูลผู้ป่วย', `${rows.length+cases.length} ราย`, 'รง.506 และแบบสอบสวน', 'blue'], ['โรคที่มีรายงานมากสุด', top ? `${top[0]} ${top[1]} ราย` : 'ยังไม่มีข้อมูล', 'ตามขอบเขตข้อมูลปัจจุบัน', 'purple'], ['งานติดตามที่ปิดแล้ว', `${completed} งาน`, 'จากงานที่มอบหมาย', 'green'], ['งานเกินกำหนด', `${overdue} งาน`, 'ต้องตรวจสอบโดยผู้รับผิดชอบ', 'orange']])}<section class="command-grid"><article class="work-panel"><div class="panel-top"><h2>ประเด็นสำหรับติดตาม</h2><small>เรียงตามจำนวนที่พบในข้อมูล</small></div>${Object.keys(byDisease).length ? ranked(byDisease,'โรค') : empty('ยังไม่มีข้อมูล', 'นำเข้าข้อมูล รง.506 หรือบันทึกแบบสอบสวนเพื่อสรุปประเด็น')}</article><article class="work-panel"><div class="panel-top"><h2>พื้นที่ที่มีรายงาน</h2><small>ภายในขอบเขตข้อมูลที่นำเข้า</small></div>${Object.keys(byTambon).length ? ranked(byTambon,'พื้นที่') : empty('ยังไม่มีข้อมูลพื้นที่', 'ข้อมูลตำบลหรืออำเภอจะแสดงเมื่อมีการบันทึก')}</article></section><p class="scope-note">รายงานนี้เป็นสรุปเชิงบริหารจากข้อมูลที่อยู่ในระบบ ณ เวลาที่เปิดดู ไม่ใช้ข้อมูลตัวอย่างและไม่สรุปสาเหตุการระบาด</p>`;
};
const knowledge = () => `${title('Knowledge Center', 'รวมแนวทางการทำงาน เอกสารแบบสอบสวน และข้อควรระวังในการใช้ข้อมูล')}<section class="knowledge-tools"><label>ค้นหาความรู้<input data-knowledge-search placeholder="เช่น แบบสอบสวน, รายงาน, ข้อมูลส่วนบุคคล" /></label><label>หมวดหมู่<select data-knowledge-category><option value="">ทุกหมวดหมู่</option><option value="forms">แบบสอบสวน</option><option value="workflow">การปฏิบัติงาน</option><option value="reports">รายงาน</option><option value="security">ข้อมูลและสิทธิ์</option></select></label></section><section class="command-grid knowledge-grid" data-knowledge-items><article class="work-panel" data-knowledge-topic data-knowledge-category="forms"><h2>📝 แบบสอบสวนโรค</h2><p>แบบฟอร์มต้นฉบับทั้ง 6 โรค อยู่ในโมดูลแบบสอบสวนโรคออนไลน์ พร้อมกรอก บันทึก และสร้าง PDF</p><button class="primary" data-view="investigation">เปิดแบบสอบสวนโรค</button></article><article class="work-panel" data-knowledge-topic data-knowledge-category="workflow"><h2>🚨 แนวทางรับสัญญาณเตือน</h2><p>ตรวจสอบความครบถ้วนของโรค พื้นที่ และวันเริ่มป่วย ก่อนทบทวนสัญญาณ Cluster หรือสั่งการติดตามเคส</p><button class="secondary" data-view="alerts">เปิดระบบแจ้งเตือน</button></article><article class="work-panel" data-knowledge-topic data-knowledge-category="workflow"><h2>🦠 การติดตามและปิดเคส</h2><p>บันทึกผู้สัมผัส กำหนดงานติดตาม และปิดเคสเมื่อดำเนินการครบตามแผนของทีมผู้รับผิดชอบ</p><button class="secondary" data-view="tracking">เปิดติดตามและควบคุมโรค</button></article><article class="work-panel" data-knowledge-topic data-knowledge-category="reports"><h2>📄 รายงานและการส่งออก</h2><p>สร้างสรุปราย Event รายงาน รง.506 และไฟล์ CSV โดยต้องตรวจทานความครบถ้วนก่อนเผยแพร่</p><button class="secondary" data-view="reports">เปิดรายงานผลสอบสวน</button></article><article class="work-panel" data-knowledge-topic data-knowledge-category="reports"><h2>🧪 การทบทวนผลห้องปฏิบัติการ</h2><p>ตรวจทานผล Positive และผูกผลตรวจกับเคสที่เกี่ยวข้องก่อนใช้ประกอบการติดตามหรือสื่อสารความเสี่ยง</p><button class="secondary" data-view="lab">เปิดรายงานห้องปฏิบัติการ</button></article><article class="work-panel" data-knowledge-topic data-knowledge-category="security"><h2>🔒 การคุ้มครองข้อมูล</h2><p>ข้อมูลผู้ป่วยต้องเข้าถึงตามหน้าที่และพื้นที่รับผิดชอบ การซ่อนเมนูไม่ทดแทนการกำหนดสิทธิ์ในฐานข้อมูล</p><button class="secondary" data-view="security">ดูสิทธิ์การเข้าถึง</button></article></section><p class="knowledge-empty" data-knowledge-empty hidden>ไม่พบหัวข้อความรู้ที่ตรงกับเงื่อนไขที่ค้นหา</p>`;

const lineNotify = () => { const {rows,cases,byDisease}=values(); const areas=[...new Set(rows.map(row=>row.tambon || row.district).filter(Boolean))]; return `${title('ส่งข้อมูลแจ้งเตือนผ่าน LINE OA', 'เตรียมข้อความสรุปจากข้อมูลในระบบเพื่อนำไปใช้กับ LINE Official Account ตามสิทธิ์ของหน่วยงาน')}<section class="work-panel"><div class="form-grid"><label>กลุ่มเป้าหมาย<select data-line-target><option>ทีม SRRT</option><option>ผู้บริหาร</option><option>ผู้รับผิดชอบรายพื้นที่</option></select></label><label>พื้นที่<select data-line-area><option value="">ทุกพื้นที่</option>${areas.map(area=>`<option value="${area}">${area}</option>`).join('')}</select></label><label>ระดับการแจ้งเตือน<select data-line-level><option>ติดตามสถานการณ์</option><option>เฝ้าระวัง</option><option>เร่งด่วน</option></select></label><label>โรค<select data-line-disease><option value="">ทุกโรค</option>${Object.keys(byDisease).map(disease=>`<option value="${disease}">${disease}</option>`).join('')}</select></label><label>จำนวนข้อมูล รง.506<input value="${rows.length} ราย" disabled /></label><label>แบบสอบสวนที่บันทึก<input value="${cases.length} ราย" disabled /></label></div><div class="form-actions"><button class="secondary" data-preview-line>ดูตัวอย่าง</button><button class="secondary" data-copy-line hidden>คัดลอกข้อความ</button><button class="primary" data-send-line>ส่งผ่าน LINE OA</button></div><div class="line-preview" data-line-preview>ยังไม่ได้สร้างข้อความแจ้งเตือน</div><p class="scope-note">ปุ่มส่งผ่าน LINE OA จะใช้งานได้เมื่อผู้ดูแลกำหนด Channel access token และสิทธิ์ผู้ใช้งานในระบบจริงแล้ว</p></section>`; };

const security = () => `${title('สิทธิ์การเข้าถึงและข้อมูลส่วนบุคคล', 'กำหนดการเข้าถึงตามบทบาทผู้ใช้งานและพื้นที่รับผิดชอบ')}<section class="work-panel"><table><thead><tr><th>ข้อมูล/ความสามารถ</th><th>ผู้ใช้งานทั่วไป</th><th>ผู้รับผิดชอบพื้นที่</th><th>ผู้ดูแลระบบ</th></tr></thead><tbody><tr><td>ตัวเลขสรุปและแผนที่</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>ดูข้อมูลผู้ป่วยรายบุคคล</td><td>—</td><td>ตามพื้นที่รับผิดชอบ</td><td>✓</td></tr><tr><td>แก้ไขแบบสอบสวน</td><td>—</td><td>ตามสิทธิ์ที่กำหนด</td><td>✓</td></tr><tr><td>นำเข้า / แก้ไข / ลบข้อมูล</td><td>—</td><td>—</td><td>✓</td></tr></tbody></table><p class="scope-note">หน้าจอนี้เป็นต้นแบบการกำหนดสิทธิ์ ฝั่งระบบจริงต้องบังคับใช้ผ่านการยืนยันตัวตนและ RLS ในฐานข้อมูล ไม่ควรพึ่งพาเพียงการซ่อนเมนู</p></section>`;

const settings = () => {
  const configured=Boolean(globalThis.NDSS_CONFIG?.supabasePublishableKey);
  const catalogue=[['User','ตรวจสอบบัญชีผู้ใช้งานและพื้นที่รับผิดชอบ','security'],['Role','กำหนดบทบาทสำหรับการใช้งานของเจ้าหน้าที่','security'],['Permission','ทบทวนขอบเขตการดู แก้ไข และส่งออกข้อมูล','security'],['Master Data','จัดการข้อมูลอ้างอิงโรค พื้นที่ และสถานะงาน','report506'],['Data Source','ตรวจสอบแหล่งข้อมูล รง.506 และแบบสอบสวน','import506'],['API','ตรวจสถานะการเชื่อมต่อบริการภายนอกอย่างปลอดภัย','settings'],['Audit Log','ทบทวนกิจกรรมสำคัญของระบบ','audit'],['System Configuration','สำรองข้อมูลและตรวจการตั้งค่าระบบ','settings']];
  return `${title('ตั้งค่าและสถานะระบบ', 'ตรวจสอบการเชื่อมต่อข้อมูลก่อนใช้งานร่วมกันในระดับหน่วยงาน')}<section class="command-grid"><article class="work-panel connection-card ${configured?'ready':'waiting'}"><span>${configured?'●':'○'}</span><h2>Supabase Database</h2><strong>${configured?'พร้อมทดสอบการเชื่อมต่อ':'ยังไม่ได้กำหนดค่า'}</strong><p>${configured?'ตรวจพบ publishable key ใน runtime configuration แล้ว':'ระบบใช้ข้อมูลภายในเบราว์เซอร์สำหรับการทดลอง จึงยังไม่ซิงก์ข้ามอุปกรณ์'}</p></article><article class="work-panel connection-card ready"><span>●</span><h2>GIS พื้นที่นราธิวาส</h2><strong>พร้อมใช้งาน</strong><p>ขอบเขตอำเภอและตำบลถูกโหลดจากไฟล์ GeoJSON ภายในระบบ</p></article></section><section class="work-panel"><div class="panel-top"><h2>ศูนย์จัดการระบบ</h2><input class="table-search" data-settings-search placeholder="ค้นหา User, Role, API หรือ Audit Log" /></div><div class="settings-catalog" data-settings-catalog>${catalogue.map(([name,detail,view])=>`<article data-settings-item><div><b>${name}</b><span>${detail}</span></div><button class="table-action" data-view="${view}">เปิด</button></article>`).join('')}</div><p class="settings-empty" data-settings-empty hidden>ไม่พบเมนูการตั้งค่าที่ค้นหา</p></section><section class="work-panel"><div class="panel-top"><h2>สำรองและกู้คืนข้อมูลในอุปกรณ์</h2><small>ใช้เฉพาะกรณียังไม่ได้เชื่อมฐานข้อมูลกลาง</small></div><p class="scope-note">ไฟล์สำรองอาจมีข้อมูลส่วนบุคคล ต้องเก็บไว้ในพื้นที่ที่หน่วยงานอนุญาต และไม่ส่งต่อให้ผู้ไม่มีสิทธิ์</p><div class="form-actions"><button class="secondary" data-backup-local>⇩ สำรองข้อมูล JSON</button><label class="primary" for="restore-local-file">⇧ กู้คืนข้อมูล</label><input id="restore-local-file" data-restore-local type="file" accept="application/json,.json" hidden /></div></section><section class="work-panel"><h2>ขั้นตอนก่อนเปิดใช้งานร่วมกัน</h2><ol class="command-list"><li>ตั้งค่า Supabase publishable key ใน <code>runtime-config.js</code> บนสภาพแวดล้อมที่ปลอดภัย</li><li>ให้ผู้ดูแลนำ <code>supabase/schema.sql</code> ไปใช้ใน SQL Editor และตรวจ RLS ให้ตรงบทบาทเจ้าหน้าที่/พื้นที่</li><li>ใช้ระบบลงชื่อเข้าใช้ และส่ง access token ของผู้ใช้ที่ผ่านการยืนยันตัวตนเท่านั้น</li><li>ห้ามใส่ service_role หรือ secret key ลงใน GitHub Pages หรือเบราว์เซอร์</li></ol><p class="scope-note">สถานะนี้ตั้งใจแสดงอย่างตรงไปตรงมา: หากยังไม่มีการตั้งค่า ระบบจะไม่แสดงข้อมูลตัวอย่างแทนข้อมูลจริง</p></section>`;
};

export function commandCenterView(id) {
  if (id === 'overview') return overview();
  if (id === 'import506') return importer();
  if (id === 'area-map') return areaMap();
  if (id === 'queue') return queue();
  if (id === 'clusters') return clusters();
  if (id === 'epidemiology') return epidemiologyTabs();
  if (id === 'tracking') return tracking();
  if (id === 'lab') return lab();
  if (id === 'alerts') return alerts();
  if (id === 'audit') return audit();
  if (id === 'report506') return report506();
  if (id === 'export') return exporter();
  if (id === 'reports') return reportsEvent();
  if (id === 'ai-brief') return aiReportCenter();
  if (id === 'executive') return executive();
  if (id === 'knowledge') return knowledge();
  if (id === 'line-notify') return lineNotify();
  if (id === 'security') return security();
  if (id === 'settings') return settings();
  return '';
}
